#  SECTOR HEATMAP — 1-row colored bar
# ═══════════════════════════════════════════════════════════════════════════
def render_sector_heatmap():
    """Render a single-row colored heatmap of sector strengths."""
    sectors = st.session_state.get('_sector_rotation') or st.session_state.get('_sector_rotation_data')
    if not sectors or not isinstance(sectors, dict):
        st.caption("Sector data not yet computed.")
        return
    rows = sectors.get('all') or sectors.get('sectors')
    if not rows:
        st.caption("Sector heatmap waiting for sector-rotation data.")
        return
    df_h = pd.DataFrame(rows)
    if df_h.empty or 'name' not in df_h.columns:
        st.caption("Sector data shape unexpected.")
        return
    pct_col = 'day_chg_pct' if 'day_chg_pct' in df_h.columns else ('pct' if 'pct' in df_h.columns else None)
    if not pct_col:
        st.caption("Sector data missing pct column.")
        return
    df_h = df_h.sort_values(pct_col, ascending=False)
    if sectors.get('rotation_bias'):
        st.caption(f"**Rotation:** {sectors['rotation_bias']}")
    # 🏭 Quality Score — the Stage-18 engine's own self-assessment: is it voting
    # into MIOS, or standing aside (thin coverage / stale data)? Makes it obvious
    # when this delayed context source is contributing vs sitting out.
    try:
        _sec = None
        _ms = st.session_state.get('_mios_state')
        if _ms is not None and getattr(_ms, 'get', None):
            _sr_r = _ms.get('stage18_sector')
            _sec = _sr_r.data if (_sr_r is not None and getattr(_sr_r, 'data', None)) else None
        if _sec:
            _fr = (f"{_sec['stale_min']:.0f} min" if _sec.get('stale_min') is not None else "—")
            if _sec.get('voting'):
                st.caption(f"🏭 **Voting** · {_sec.get('risk_mode','—')} · breadth "
                           f"{_sec.get('breadth_pct','—')}% · coverage {_sec.get('coverage','—')}/11 "
                           f"· fresh {_fr} · reliability {_sec.get('stars','')}")
            else:
                st.caption(f"🏭 **Not voting** (context stood aside) · coverage "
                           f"{_sec.get('coverage','—')}/11 · fresh {_fr} "
                           f"· reliability {_sec.get('stars','')}")
    except Exception:
        pass
    fig = go.Figure(data=go.Heatmap(
        z=[df_h[pct_col].astype(float).tolist()],
        x=df_h['name'].astype(str).tolist(),
        y=['Sectors'],
        colorscale=[[0, '#ff4444'], [0.5, '#222'], [1, '#00cc66']],
        zmid=0,
        text=[[f"{p:+.1f}%" for p in df_h[pct_col]]],
        texttemplate='%{text}',
        showscale=False,
        hovertemplate='<b>%{x}</b><br>%{text}<extra></extra>',
    ))
    fig.update_layout(
        height=110, margin=dict(l=10, r=10, t=10, b=10),
        plot_bgcolor='#0e1117', paper_bgcolor='#0e1117', font=dict(color='white'),
        xaxis=dict(tickfont=dict(size=10)),
        yaxis=dict(showticklabels=False),
    )
    st.plotly_chart(fig, use_container_width=True)


