            _trap = _cmce_r.get('trap_risk', '-')
            _idx_lines = []
            for _m in (_cmce_r.get('indian_markets') or [])[:3]:
                _flag = '✅' if _m.get('confirmed') else '➖'
                _idx_lines.append(f"  {_flag} {_m.get('name','-')[:12]}: {_m.get('pattern','-')[:22]} (+{_m.get('score',0)})")
            _rev_lines = []
