                            # Classification
                            direct_instruments = ['SENSEX', 'BANKNIFTY', 'NIFTY IT', 'RELIANCE', 'ICICIBANK', 'GOLD', 'S&P 500', 'JAPAN 225', 'HANG SENG', 'UK 100']
